index e0bf380..fcc6a35 100644
--- a/Sources/SwiftJLI/Native/Decoder/JLIDecoder.swift
+++ b/Sources/SwiftJLI/Native/Decoder/JLIDecoder.swift
@@ -6,6 +6,29 @@ import Accelerate
 #endif
 import Foundation

+private protocol LosslessLookupStore {
+    static var bytesPerSample: Int { get }
+    static func write(_ value: Int32, _ output: UnsafeMutablePointer<UInt8>, _ x: Int, _ pt: Int)
+}
+
+private enum LosslessLookupStore8: LosslessLookupStore {
+    static let bytesPerSample = 1
+    @inline(__always)
+    static func write(_ value: Int32, _ output: UnsafeMutablePointer<UInt8>, _ x: Int, _ pt: Int) {
+        output[x] = UInt8(clamping: Int(value) << pt)
+    }
+}
+
+private enum LosslessLookupStore16: LosslessLookupStore {
+    static let bytesPerSample = 2
+    @inline(__always)
+    static func write(_ value: Int32, _ output: UnsafeMutablePointer<UInt8>, _ x: Int, _ pt: Int) {
+        let shifted = UInt16(clamping: Int(value) << pt)
+        output[x * 2] = UInt8(truncatingIfNeeded: shifted)
+        output[x * 2 + 1] = UInt8(shifted >> 8)
+    }
+}
+
 /// The jpegli-compatible JPEG decoder.
 ///
 /// `JLIDecoder` decompresses JPEG data, automatically detecting advanced features
@@ -1072,7 +1095,29 @@ struct JLIDecoder: Sendable {
         predictor: Int, half: Int32, table: HuffmanTable, reader: inout BitReader,
         pointTransform pt: Int, segmentRows: Int, lookup: LosslessLookahead
     ) throws {
-        let bps = destination.bytesPerSample
+        switch destination.bytesPerSample {
+        case 1:
+            try losslessGrayLookupRows(destination, width: w, height: h,
+                predictor: predictor, half: half, table: table, reader: &reader,
+                pointTransform: pt, segmentRows: segmentRows, lookup: lookup,
+                store: LosslessLookupStore8.self)
+        case 2:
+            try losslessGrayLookupRows(destination, width: w, height: h,
+                predictor: predictor, half: half, table: table, reader: &reader,
+                pointTransform: pt, segmentRows: segmentRows, lookup: lookup,
+                store: LosslessLookupStore16.self)
+        default:
+            throw JLIError.decodingFailed("invalid lossless destination layout")
+        }
+    }
+
+    private static func losslessGrayLookupRows<Store: LosslessLookupStore>(
+        _ destination: BorrowedSampleDestination, width w: Int, height h: Int,
+        predictor: Int, half: Int32, table: HuffmanTable, reader: inout BitReader,
+        pointTransform pt: Int, segmentRows: Int, lookup: LosslessLookahead,
+        store: Store.Type
+    ) throws {
+        let bps = Store.bytesPerSample
         guard bps == 1 || bps == 2, destination.rowBytes >= w * bps else {
             throw JLIError.decodingFailed("invalid lossless destination layout")
         }
@@ -1101,7 +1146,7 @@ struct JLIDecoder: Sendable {
